// Des: Page actions: scroll, click, consent walls, scripted steps
// Flo: scroll until height stable x3 > click by selector or visible text > consent selectors > steps file ops with step and time caps; never types into password fields
// I/O: Page (caller) + caps > rows loaded, clicks made, extracted text; errors SecretField StepLimit TimeUp
// ===================================================================
const std = @import("std"); const mem = std.mem; const pg = @import("nt-brow-page.zig");
const CF = .{ .nap = 400, .calm = 3, .more = 40 };
pub const Step = struct { op: []const u8, url: []const u8 = "", sele: []const u8 = "", text: []const u8 = "", ms: u32 = 0 };
pub const Acts = struct { scrl: u32 = 0, clic: []const u8 = "", cons: bool = false, steps: []const Step = &.{}, pub fn any(self: Acts) bool { return self.scrl > 0 or self.clic.len > 0 or self.cons or self.steps.len > 0; } };
pub fn stepsRead(aren: std.mem.Allocator, text: []const u8, maxz: u32) ![]const Step { const lst = std.json.parseFromSliceLeaky([]const Step, aren, text, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadSteps; if (lst.len > maxz) return error.StepLimit; for (lst) |stp| { const ok = mem.eql(u8, stp.op, "goto") or mem.eql(u8, stp.op, "click") or mem.eql(u8, stp.op, "clicktext") or mem.eql(u8, stp.op, "type") or mem.eql(u8, stp.op, "wait") or mem.eql(u8, stp.op, "waitsel") or mem.eql(u8, stp.op, "scroll") or mem.eql(u8, stp.op, "extract"); if (!ok) return error.BadSteps; } return lst; }
pub fn scroll(self: *pg.Page, aren: std.mem.Allocator, maxz: u32) u32 { var cnt: u32 = 0; var same: u32 = 0; var last: i64 = -1; while (cnt < maxz and self.left() > 0) : (cnt += 1) { _ = self.evalNum(aren, "window.scrollTo(0,document.documentElement.scrollHeight),1"); self.nap(CF.nap); const hgt = self.evalNum(aren, "document.documentElement.scrollHeight"); if (hgt == last) { same += 1; if (same >= CF.calm) break; } else same = 0; last = hgt; } return cnt; }
pub fn clickSel(self: *pg.Page, aren: std.mem.Allocator, sele: []const u8) !bool { const qry = try std.json.Stringify.valueAlloc(aren, sele, .{}); const expr = try std.fmt.allocPrint(aren, "(function(s){{var e=document.querySelector(s);if(!e)return 0;e.scrollIntoView();e.click();return 1}})({s})", .{qry}); return self.evalNum(aren, expr) == 1; }
pub fn clickText(self: *pg.Page, aren: std.mem.Allocator, text: []const u8) !bool { const qry = try std.json.Stringify.valueAlloc(aren, text, .{}); const expr = try std.fmt.allocPrint(aren, "(function(t){{t=t.toLowerCase();var l=document.querySelectorAll('button,a,[role=button],input[type=button],input[type=submit]');for(var i=0;i<l.length;i++){{var x=(l[i].innerText||l[i].value||'').trim().toLowerCase();if(x.indexOf(t)>=0){{l[i].scrollIntoView();l[i].click();return 1}}}}return 0}})({s})", .{qry}); return self.evalNum(aren, expr) == 1; }
pub fn loadMore(self: *pg.Page, aren: std.mem.Allocator, text: []const u8, maxz: u32) !u32 { var cnt: u32 = 0; while (cnt < @min(maxz, CF.more) and self.left() > 0) : (cnt += 1) { const before = self.evalNum(aren, "document.body.innerText.length"); if (!try clickText(self, aren, text)) break; self.nap(CF.nap); self.settle(aren); if (self.evalNum(aren, "document.body.innerText.length") <= before) { cnt += 1; break; } } return cnt; }
pub fn consent(self: *pg.Page, aren: std.mem.Allocator, sels: []const []const u8) !u32 { var cnt: u32 = 0; for (sels) |sel| { if (try clickSel(self, aren, sel)) { cnt += 1; self.nap(CF.nap); } } if (cnt > 0) self.settle(aren); return cnt; }
fn typeIn(self: *pg.Page, aren: std.mem.Allocator, sele: []const u8, text: []const u8) !void { const qs = try std.json.Stringify.valueAlloc(aren, sele, .{}); const qt = try std.json.Stringify.valueAlloc(aren, text, .{}); const expr = try std.fmt.allocPrint(aren, "(function(s,t){{var e=document.querySelector(s);if(!e)return 0;var ty=(e.getAttribute('type')||'').toLowerCase();var ac=(e.getAttribute('autocomplete')||'').toLowerCase();if(ty==='password'||ac.indexOf('password')>=0||ac.indexOf('one-time')>=0)return -1;e.focus();e.value=t;e.dispatchEvent(new Event('input',{{bubbles:true}}));e.dispatchEvent(new Event('change',{{bubbles:true}}));return 1}})({s},{s})", .{ qs, qt }); const res = self.evalNum(aren, expr); if (res == -1) return error.SecretField; if (res != 1) return error.NoElement; }
pub fn run(self: *pg.Page, aren: std.mem.Allocator, acts: Acts, sels: []const []const u8, scrm: u32, outp: *std.ArrayList(u8)) !void { if (acts.cons) _ = try consent(self, aren, sels); if (acts.clic.len > 0) _ = try loadMore(self, aren, acts.clic, scrm); if (acts.scrl > 0) _ = scroll(self, aren, @min(acts.scrl, scrm)); for (acts.steps) |stp| { if (self.left() == 0) return error.TimeUp; if (mem.eql(u8, stp.op, "goto")) { try self.navigate(aren, stp.url, .{ .time_mill = self.left() }); } else if (mem.eql(u8, stp.op, "click")) { if (!try clickSel(self, aren, stp.sele)) return error.NoElement; self.nap(CF.nap); self.settle(aren); } else if (mem.eql(u8, stp.op, "clicktext")) { if (!try clickText(self, aren, stp.text)) return error.NoElement; self.nap(CF.nap); self.settle(aren); } else if (mem.eql(u8, stp.op, "type")) { try typeIn(self, aren, stp.sele, stp.text); } else if (mem.eql(u8, stp.op, "wait")) { self.nap(@min(stp.ms, 30000)); } else if (mem.eql(u8, stp.op, "waitsel")) { const qry = try std.json.Stringify.valueAlloc(aren, stp.sele, .{}); const expr = try std.fmt.allocPrint(aren, "document.querySelector({s})!==null", .{qry}); var okay = false; while (self.left() > 0) { if (self.evalNum(aren, expr) == 1) { okay = true; break; } self.nap(250); } if (!okay) return error.TimeUp; } else if (mem.eql(u8, stp.op, "scroll")) { _ = scroll(self, aren, scrm); } else if (mem.eql(u8, stp.op, "extract")) { const qry = try std.json.Stringify.valueAlloc(aren, stp.sele, .{}); const expr = try std.fmt.allocPrint(aren, "Array.from(document.querySelectorAll({s})).map(function(e){{return e.innerText}}).join('\\n')", .{qry}); const txt = try self.evalStr(aren, expr); var itr = mem.splitScalar(u8, txt, '\n'); while (itr.next()) |ln| { if (ln.len == 0) continue; try outp.print(aren, "<div data-scra-extract=\"{s}\">", .{"x"}); for (ln) |chr| switch (chr) { '<' => try outp.appendSlice(aren, "&lt;"), '>' => try outp.appendSlice(aren, "&gt;"), '&' => try outp.appendSlice(aren, "&amp;"), else => try outp.append(aren, chr) }; try outp.appendSlice(aren, "</div>"); } } } }
